/*
 * Grid data. This is the basic data structure that represents what is shown on
 * screen.
 *
 * A grid is a grid of cells (struct grid_cell). Lines are not allocated until
 * cells in that line are written to. The grid is split into history and
 * viewable data with the history starting at row (line) 0 and extending to
 * (hsize - 1); from hsize to hsize + (sy - 1) is the viewable data. All
 * functions in this file work on absolute coordinates, grid-view.c has
 * functions which work on the screen data.
 */

/* Default grid cell data. */
#if defined(TMUX_NATIVE_211BSD) && defined(TMUX_MILESTONE)
/* The native compiler cannot initialize bit fields statically. */
struct grid_cell grid_default_cell;
#else
const struct grid_cell grid_default_cell = { 0, 0, 8, 8, ' ' };
#endif

void
grid_init_default(void)
{
#if defined(TMUX_NATIVE_211BSD) && defined(TMUX_MILESTONE)
	grid_default_cell.attr = 0;
	grid_default_cell.flags = 0;
	grid_default_cell.fg = 8;
	grid_default_cell.bg = 8;
	grid_default_cell.data = ' ';
#endif
}

